{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Acamprosate, a small highly polar ionized molecule with an amide and sulfonic acid, has a mean absolute oral bioavailability of 11 ± 1% in healthy humans after a 666 mg oral dose versus IV, directly demonstrating that this physicochemical profile falls below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "The cyclic peptide octreotide has an absolute oral bioavailability of only 0.6 ± 0.4% in healthy volunteers, showing that cyclic peptide scaffolds with multiple amides and polar groups can have extremely low oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Microcystin-LR, a large polar cyclic peptide, is reported to have low oral bioavailability in humans based on in vitro data, supporting poor absorption for polar cyclic peptide-like structures.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted low oral bioavailability (<20%): the query is a highly polar, fully ionized dicarboxylic acid diketopiperazine with very low estimated permeability. The strongest transferable evidence, acamprosate (human F ≈ 11%), directly supports a sub-20% F, and cyclic peptide analogues also show very low oral absorption. High-F small polar comparators are not transferable because they rely on active transport or are much more lipophilic.",
  "evidence_gaps": [
    "No direct human oral bioavailability measurement exists for the exact diketopiperazine scaffold.",
    "Possible active uptake or prodrug strategies could alter F, but no evidence supports them for this molecule.",
    "High-F small polar molecules such as L-arginine are not transferable because their absorption depends on specific amino acid transporters absent in the query."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
